using System;
using System.Linq;
using System.Collections.Generic;

namespace Taruck.CharacterCreation
{
    // PHB 2014 and PHB 2024. Temporary Rage benefits never alter permanent attack or HP fields.
    public static class CharacterBarbarianRules
    {
        public static bool Active(CharacterCreationDraft d) => d.characterClass == "barbarian";
        internal static bool Modern(CharacterCreationDraft d) => d.edition == RulesEdition.Rules2024;
        public static readonly string[] Classic = { "berserker", "totem" };
        public static readonly string[] Revised = { "berserker", "wildheart", "worldtree", "zealot" };
        public static readonly string[] Animals = { "bear", "eagle", "wolf" };
        public static readonly string[] AnimalNames = { "Ведмідь", "Орел", "Вовк" };
        public static readonly string[] Aspects = { "owl", "panther", "salmon" };
        public static readonly string[] AspectNames = { "Сова", "Пантера", "Лосось" };
        public static string[] Options(CharacterCreationDraft d) => Modern(d) ? Revised : Classic;
        public static string Name(string id) => id == "berserker" ? "Шлях берсерка" : id == "totem" ? "Шлях тотемного воїна" : id == "wildheart" ? "Шлях дикого серця" : id == "worldtree" ? "Шлях світового дерева" : id == "zealot" ? "Шлях ревнителя" : "";
        public static bool Is(CharacterCreationDraft d, string id) => Active(d) && d.level >= 3 && d.subclass == id && Options(d).Contains(id);
        public static int RageDamage(CharacterCreationDraft d) => d.level >= 16 ? 4 : d.level >= 9 ? 3 : 2;
        public static bool UnlimitedRage(CharacterCreationDraft d) => Active(d) && !Modern(d) && d.level >= 20;
        public static int Rages(CharacterCreationDraft d) => d.level >= 17 ? 6 : d.level >= 12 ? 5 : d.level >= 6 ? 4 : d.level >= 3 ? 3 : 2;
        public static int HealingDice(CharacterCreationDraft d) => d.level >= 17 ? 7 : d.level >= 12 ? 6 : d.level >= 6 ? 5 : 4;
        internal static int Masteries(CharacterCreationDraft d) => d.level >= 10 ? 4 : d.level >= 4 ? 3 : 2;
        public static string ChoiceError(CharacterCreationDraft d)
        {
            if (!Active(d) || d.level < 3) return null;
            if (!Options(d).Contains(d.subclass)) return "Обери шлях варвара.";
            if (Is(d, "totem") && (!Animals.Contains(d.barbarianSpirit) || d.level >= 6 && !Animals.Contains(d.barbarianAspect) || d.level >= 14 && !Animals.Contains(d.barbarianAttunement))) return "Обери тотемну тварину для кожного доступного рівня.";
            if (Is(d, "wildheart") && d.level >= 6 && !Aspects.Contains(d.barbarianAspect)) return "Обери аспект дикої природи.";
            return null;
        }
        public static string[] Spells(CharacterCreationDraft d) => Is(d, "totem") || Is(d, "wildheart")
            ? new[] { "Beast Sense", "Speak with Animals" }.Concat(d.level >= 10 ? new[] { "Commune with Nature" } : Array.Empty<string>()).ToArray() : Array.Empty<string>();
        internal static CreatedCharacterStats Calculate(CharacterCreationDraft d)
        {
            int[] s = CharacterCreationRules.Scores(d);
            var skills = CharacterCreationRules.BackgroundSkills(d).Concat(d.classSkills).Where(i => i >= 0).Distinct().ToList();
            if (Modern(d) && d.level >= 3 && d.primalKnowledgeSkill >= 0) skills.Add(d.primalKnowledgeSkill);
            if (Modern(d) && d.species == "human" && d.humanSkill >= 0) skills.Add(d.humanSkill);
            return new CreatedCharacterStats {
                scores = s, skills = skills.Distinct().ToList(), hitPoints = CharacterCreationRules.ClassHitPoints(d, CharacterCreationRules.Modifier(s[2])),
                armorClass = 10 + CharacterCreationRules.Modifier(s[1]) + CharacterCreationRules.Modifier(s[2]),
                initiative = CharacterCreationRules.Modifier(s[1]), speed = (CharacterSpeciesRules.IsDwarf(d) && !Modern(d) ? 25 : 30) + (d.level >= 5 ? 10 : 0),
                passivePerception = 10 + CharacterCreationRules.Modifier(s[4]) + (skills.Contains(11) ? CharacterLegacySpeciesRules.Proficiency(d) : 0),
                speciesName = CharacterSpeciesRules.Name(d), backgroundName = CharacterBackgroundRules.Find(d)?.name ?? "",
                equipment = CharacterCreationRules.Equipment(d),
                proficiencies = "Легкі та середні обладунки, щити, проста й військова зброя. Ряткидки: Сила, Статура.",
                features = Features(d) + "\n" + SubclassFeatures(d) + CharacterBackgroundRules.Features(d)
            };
        }
        internal static string Features(CharacterCreationDraft d)
        {
            bool modern = Modern(d); int level = d.level;
            var lines = new List<string> {
                "Захист без обладунку: КО = 10 + модифікатори Спритності та Статури; щит дозволений.",
                RageDamage(d) == 4 ? "Лють: +4 шкоди атакам Силою за умов класу." : RageDamage(d) == 3 ? "Лють: +3 шкоди атакам Силою за умов класу." : "Лють: +2 шкоди атакам Силою за умов класу.",
                "Під час Люті: опір дробильній, колючій та рубаній шкоді; перевага на перевірки й ряткидки Сили. Не можна накладати спели або підтримувати концентрацію.",
                modern ? "Лють 2024: бонусна дія без важкого обладунку; короткий відпочинок повертає 1 використання, довгий — усі. Підтримуй до 10 хв атакою по ворогу, примусовим ряткидком ворога або бонусною дією; закінчується при недієздатності чи важкому обладунку."
                    : "Лють 2014: бонусна дія; до 1 хв. Без важкого обладунку; закінчується при непритомності або наприкінці ходу без атаки ворога й отриманої шкоди. Бонусною дією можна завершити. Довгий відпочинок повертає використання."
            };
            if (UnlimitedRage(d)) lines.Add("Лють без обмеження використань.");
            if (modern) lines.Add("Майстерність зброї: " + string.Join(", ", d.weaponMasteries.Where(i => i >= 0 && i < CharacterCreationRules.MasteryWeapons.Count).Select(i => CharacterCreationRules.MasteryWeapons[i])) + ".");
            if (level >= 2) {
                lines.Add(modern ? "Безрозсудна атака: перевага на атаки Силою до наступного ходу, але атаки проти тебе теж із перевагою." : "Безрозсудна атака: перевага на атаки ближнього бою Силою цього ходу, але атаки проти тебе теж із перевагою.");
                lines.Add(modern ? "Чуття небезпеки: перевага на ряткидки Спритності, якщо ти не недієздатний." : "Чуття небезпеки: перевага на ряткидки Спритності проти видимих ефектів; не діє при сліпоті, глухоті чи недієздатності.");
            }
            if (modern && level >= 3) lines.Add("Первісне знання: додаткова навичка; під час Люті Акробатику, Залякування, Уважність, Скритність і Виживання можна перевіряти Силою.");
            if (level >= 5) lines.Add("Додаткова атака: дві атаки дією Атака. Швидкий рух: +10 футів без важкого обладунку; швидкість уже врахована.");
            if (level >= 7) lines.Add(modern ? "Дикий інстинкт: перевага на ініціативу. Інстинктивний стрибок: при вході в Лють перемістися на половину швидкості." : "Дикий інстинкт: перевага на ініціативу; при несподіванці можеш діяти, якщо не недієздатний і спершу входиш у Лють.");
            if (level >= 9) {
                if (modern) {
                    lines.Add(level >= 17 ? "Жорстокий удар: без переваги Безрозсудної атаки для однієї атаки Силою без перешкоди — +2к10 шкоди та два різні ефекти при влучанні." : "Жорстокий удар: без переваги Безрозсудної атаки для однієї атаки Силою без перешкоди — +1к10 шкоди та один ефект при влучанні.");
                    lines.Add("Ефекти жорстокого удару: відштовхнути на 15 футів і підійти на половину швидкості без провокованих атак, або зменшити швидкість цілі на 15 футів до твого наступного ходу; сповільнення не складається.");
                    if (level >= 13) lines.Add("Додаткові ефекти удару: перешкода на наступний ряткидок і заборона провокованих атак до твого наступного ходу; або +5 до наступної атаки іншої істоти по цілі до твого наступного ходу, без складання бонусів.");
                } else lines.Add(level >= 17 ? "Жорстокий критичний удар: +3 кістки зброї при критичному влучанні ближньою атакою." : level >= 13 ? "Жорстокий критичний удар: +2 кістки зброї при критичному влучанні ближньою атакою." : "Жорстокий критичний удар: +1 кістка зброї при критичному влучанні ближньою атакою.");
            }
            if (level >= 11) lines.Add(modern ? "Невпинна лють: при падінні до 0 ОЗ у Люті без миттєвої смерті ряткидок Статури СК 10 залишає ОЗ = подвоєний рівень варвара. Після кожного використання СК +5; короткий або довгий відпочинок скидає СК до 10." : "Невпинна лють: при падінні до 0 ОЗ у Люті без миттєвої смерті ряткидок Статури СК 10 залишає 1 ОЗ. Після кожного використання СК +5; короткий або довгий відпочинок скидає СК до 10.");
            if (level >= 15) lines.Add(modern ? "Стійка лють: при ініціативі віднови всі використання Люті раз за довгий відпочинок. Лють триває 10 хв без підтримання; закінчується при непритомності чи важкому обладунку." : "Стійка лють: протягом хвилини Лють закінчується достроково тільки при непритомності або за твоїм бажанням.");
            if (level >= 18) lines.Add(modern ? "Нездоланна міць: результат перевірки чи ряткидка Сили не нижчий за значення Сили." : "Нездоланна міць: результат перевірки Сили не нижчий за значення Сили.");
            if (level >= 20) lines.Add(modern ? "Первісний чемпіон: Сила й Статура +4, межа 25; уже враховано." : "Первісний чемпіон: Сила й Статура +4, межа 24; уже враховано.");
            return string.Join("\n", lines);
        }
        internal static string SubclassFeatures(CharacterCreationDraft d)
        {
            var lines = new List<string>();
            if (d.level < 3) return "";
            int level = d.level;
            if (Is(d, "berserker")) {
                lines.Add(Modern(d) ? RageDamage(d) == 4 ? "Шаленство: під час Люті й Безрозсудної атаки перше влучання Силою за твій хід завдає +4к6 шкоди того самого типу." : RageDamage(d) == 3 ? "Шаленство: під час Люті й Безрозсудної атаки перше влучання Силою за твій хід завдає +3к6 шкоди того самого типу." : "Шаленство: під час Люті й Безрозсудної атаки перше влучання Силою за твій хід завдає +2к6 шкоди того самого типу." : "Шаленство: обери при вході в Лють; з наступного ходу одна атака ближньою зброєю бонусною дією щохід. Після Люті — один рівень виснаження.");
                if (level >= 6) lines.Add(Modern(d) ? "Бездумна лють: імунітет до причарування й страху в Люті; обидва стани завершуються при вході в Лють." : "Бездумна лють: не можна причарувати чи налякати в Люті; наявний ефект призупиняється на час Люті.");
                if (level >= (Modern(d) ? 10 : 14)) lines.Add(Modern(d) ? "Відплата: реакцією на шкоду від істоти в 5 футах атакуй її ближньою зброєю або беззбройним ударом." : "Відплата: реакцією на шкоду від істоти в 5 футах атакуй її ближньою зброєю.");
                if (level >= (Modern(d) ? 14 : 10)) lines.Add(Modern(d) ? "Загрозлива присутність: бонусна дія; обрані істоти в 30 футах — ряткидок Мудрості СК 8 + Сила + майстерність проти страху на 1 хв, повтор наприкінці кожного ходу. Раз за довгий відпочинок; витрата Люті відновлює використання." : "Загрозлива присутність: дія, видима ціль у 30 футах, яка бачить або чує тебе; ряткидок Мудрості СК 8 + Харизма + майстерність проти страху до кінця твого наступного ходу. Підтримуй дією; кінець без видимості чи далі 60 футів. Успіх дає цілі імунітет на 24 год.");
            }
            if (Is(d, "totem")) {
                lines.Add("Шукач духів: Чуття звіра й Розмова з тваринами лише ритуалами; не можна накладати під час Люті.");
                lines.Add(d.barbarianSpirit == "bear" ? "Тотем ведмедя: у Люті опір усій шкоді, крім психічної." : d.barbarianSpirit == "eagle" ? "Тотем орла: у Люті без важкого обладунку провоковані атаки проти тебе з перешкодою; Ривок бонусною дією." : "Тотем вовка: у Люті союзники мають перевагу на ближні атаки по твоїх ворогах у 5 футах від тебе.");
                if (level >= 6) lines.Add(d.barbarianAspect == "bear" ? "Аспект ведмедя: подвоєна вантажопідйомність; перевага на Силу для штовхання, тягання, піднімання та ламання предметів." : d.barbarianAspect == "eagle" ? "Аспект орла: бачиш деталі за милю як за 100 футів; тьмяне світло не дає перешкоди на Уважність." : "Аспект вовка: вистежування швидким темпом, скритний рух нормальним темпом.");
                if (level >= 10) lines.Add("Мандрівник духів: Спілкування з природою лише ритуалом.");
                if (level >= 14) lines.Add(d.barbarianAttunement == "bear" ? "Єднання ведмедя: у Люті вороги в 5 футах мають перешкоду на атаки інших цілей; потрібні зір або слух, не діє при імунітеті до страху чи проти іншого носія цієї здібності." : d.barbarianAttunement == "eagle" ? "Єднання орла: у Люті політ зі швидкістю ходьби; падаєш наприкінці ходу без іншої опори." : "Єднання вовка: після влучання ближньою зброєю в Люті бонусною дією збий Велику або меншу ціль з ніг.");
            }
            if (Is(d, "wildheart")) {
                lines.Add("Мовець тварин: Чуття звіра й Розмова з тваринами лише ритуалами; базова характеристика — Мудрість.");
                lines.Add("Лють дикої природи — обирай при кожній Люті: Ведмідь — опір усій шкоді, крім силової, некротичної, психічної й променистої; Орел — Ривок і Відхід при вході та бонусною дією; Вовк — союзникам перевага на всі атаки ворогів у 5 футах від тебе.");
                if (level >= 6) lines.Add(d.barbarianAspect == "owl" ? "Аспект сови: темнозір 60 футів або +60 футів до наявного; аспект можна змінити після довгого відпочинку." : d.barbarianAspect == "panther" ? "Аспект пантери: швидкість лазіння дорівнює ходьбі; аспект можна змінити після довгого відпочинку." : "Аспект лосося: швидкість плавання дорівнює ходьбі; аспект можна змінити після довгого відпочинку.");
                if (level >= 10) lines.Add("Мовець природи: Спілкування з природою лише ритуалом; Мудрість.");
                if (level >= 14) lines.Add("Сила дикої природи — обирай при кожній Люті: Сокіл — політ зі швидкістю ходьби без обладунків; Лев — ворогам у 5 футах перешкода на атаки інших цілей, крім іншого носія цієї здібності; Баран — ближнє влучання збиває Велику або меншу ціль з ніг.");
            }
            if (Is(d, "worldtree")) {
                lines.Add("Життя дерева: при вході в Лють отримай тимчасові ОЗ = рівень варвара. На початку кожного свого ходу дай іншій істоті в 10 футах тимчасові ОЗ = к6 за кожну одиницю бонусу шкоди Люті; залишок зникає після Люті.");
                if (level >= 6) lines.Add("Гілки дерева: реакція в Люті на початок ходу видимої істоти в 30 футах; ряткидок Сили СК 8 + Сила + майстерність, провал — телепорт до тебе в 5 футів або найближче вільне місце. Можеш знизити швидкість до 0 до кінця її ходу.");
                if (level >= 10) lines.Add("Таранне коріння: у твій хід досяжність важкої або універсальної ближньої зброї +10 футів; при влучанні додай Відштовхування або Повалення до іншої майстерності зброї.");
                if (level >= 14) lines.Add("Подорож деревом: при вході в Лють і бонусною дією в Люті телепорт у видиме місце до 60 футів. Раз за Лють — до 150 футів із шістьма охочими істотами в 10 футах; розмісти їх у 10 футах від місця прибуття.");
            }
            if (Is(d, "zealot")) {
                lines.Add("Божественна лють: перша ціль, влучена зброєю чи беззбройним ударом за твій хід у Люті, отримує +1к6 + половина рівня варвара (вниз) некротичної або променистої шкоди на вибір при кожному влучанні.");
                lines.Add("Воїн богів: запас к12 для самолікування бонусною дією; кількість відстежується на сторінці магії, відновлення після довгого відпочинку.");
                if (level >= 6) lines.Add("Фанатична зосередженість: раз за кожну Лють перекинь провалений ряткидок із бонусом шкоди Люті до нового результату; прийми новий результат.");
                if (level >= 10) lines.Add("Ревна присутність: бонусна дія; до десяти інших істот у 60 футах отримують перевагу на атаки й ряткидки до твого наступного ходу. Раз за довгий відпочинок; витрата Люті відновлює використання.");
                if (level >= 14) lines.Add("Лють богів: при вході в Лють божественна форма на 1 хв або до 0 ОЗ, раз за довгий відпочинок. Політ зі швидкістю ходьби з зависанням, опір некротичній, психічній і променистій шкоді. Реакція при падінні істоти в 30 футах до 0 ОЗ: витрать Лють, щоб натомість дати ОЗ = рівень варвара.");
            }
            return string.Join("\n", lines);
        }
    }
}
